<?php require __DIR__.'/includes/bootstrap.php';if($_SERVER['REQUEST_METHOD']==='POST'){csrf_verify();$mobile=preg_replace('/[^0-9]/','',$_POST['mobile'] ?? '');if(strlen($mobile)===12 && substr($mobile,0,2)==='91'){$mobile=substr($mobile,2);}elseif(strlen($mobile)===11 && substr($mobile,0,1)==='0'){$mobile=substr($mobile,1);}$email=strtolower(trim($_POST['email'] ?? ''));if(strlen($mobile)<10){flash('Enter a valid mobile number.','error');}elseif(strlen($_POST['password'] ?? '') > 0 && strlen($_POST['password']) < 8){flash('Password must be at least 8 characters, or leave it blank to use OTP login.','error');}elseif(!in_array($_POST['category'] ?? '',['plumbing','electrician'],true)){flash('Choose a valid service category.','error');}else{try{$fallbackPassword=password_hash($_POST['password'] !== '' ? $_POST['password'] : bin2hex(random_bytes(16)),PASSWORD_DEFAULT);$pdo->prepare("INSERT INTO workers(name,mobile,email,password_hash,category,skills,experience_years,address,service_area,working_hours,starting_price) VALUES(?,?,?,?,?,?,?,?,?,?,?)")->execute([trim($_POST['name']),$mobile,$email ?: null,$fallbackPassword,$_POST['category'],trim($_POST['skills']),intval($_POST['experience']),trim($_POST['address']),trim($_POST['area']),trim($_POST['hours']),max(0,floatval($_POST['starting_price'] ?? 299))]);flash('Application submitted. An admin will review your profile.');redirect('worker-login.php');}catch(PDOException $e){flash('An account with these details already exists.','error');}}}$pageTitle='Join NearbyHand';require __DIR__.'/includes/header.php'; ?>
<div class="auth-wrap"><form method="post" class="auth-card" style="max-width:650px"><h1>Become a NearbyHand professional</h1><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><div class="form-grid"><label class="field"><span>Full name</span><input name="name" required></label><label class="field"><span>Mobile</span><input name="mobile" required></label><label class="field"><span>Email</span><input type="email" name="email"></label><label class="field"><span>Password (optional)</span><input type="password" name="password" minlength="8" placeholder="Leave blank to use mobile OTP"></label><label class="field"><span>Service category</span><select name="category" required><option value="plumbing">Plumbing</option><option value="electrician">Electrician</option></select></label><label class="field"><span>Experience (years)</span><input type="number" min="0" name="experience"></label></div><label class="field"><span>Skills</span><textarea name="skills" required></textarea></label><label class="field"><span>Home address</span><input name="address" required></label><div class="form-grid"><label class="field"><span>Service area</span><input name="area" placeholder="e.g. Central area" required></label><label class="field"><span>Working hours</span><input name="hours" placeholder="9 AM - 7 PM" required></label><label class="field"><span>Starting price (₹)</span><input type="number" min="0" name="starting_price" value="299" required></label></div><button class="btn btn-primary">Submit application</button></form></div><?php require __DIR__.'/includes/footer.php'; ?>